#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int age;
    float gpa;
};

int main() {
    Student s1; // struct کا آبجیکٹ بنایا
    s1.name = "Ali";
    s1.age = 20;
    s1.gpa = 3.8;

    cout << "Name: " << s1.name << endl;
    cout << "Age: " << s1.age << endl;
    cout << "GPA: " << s1.gpa << endl;
    return 0;
}
